<template>
  <section class="wardrobe-page">
    <UiPageHeader title="Шкаф и образы" eyebrow="Личная коллекция" description="Соберите вещи в одном месте и создавайте готовые сочетания.">
      <template #actions>
        <UiButton variant="secondary" :disabled="items.length < 2" @click="openLookCreate">Собрать образ</UiButton>
        <UiButton @click="openItemCreate">Добавить вещь</UiButton>
      </template>
    </UiPageHeader>

    <section class="wardrobe-overview">
      <button type="button" :class="{ active: activeTab === 'items' }" @click="activeTab='items'"><span><UiIcon name="hanger" /></span><div><small>Вещи</small><strong>{{ activeItemsCount }}</strong></div></button>
      <button type="button" :class="{ active: activeTab === 'looks' }" @click="activeTab='looks'"><span><UiIcon name="sparkles" /></span><div><small>Образы</small><strong>{{ looks.length }}</strong></div></button>
      <article><span><UiIcon name="heart" /></span><div><small>Любимые</small><strong>{{ favoriteCount }}</strong></div></article>
    </section>

    <section class="wardrobe-toolbar panel">
      <UiInput v-model="search" type="search" :placeholder="activeTab==='items' ? 'Найти вещь, бренд или размер' : 'Найти образ'" />
      <template v-if="activeTab==='items'">
        <label><span>Категория</span><UiSelect v-model="categoryFilter"><option value="all">Все категории</option><option v-for="category in categories" :key="category.value" :value="category.value">{{ category.label }}</option></UiSelect></label>
      </template>
      <template v-else>
        <label><span>Ситуация</span><UiSelect v-model="occasionFilter"><option value="all">Все образы</option><option v-for="occasion in occasions" :key="occasion.value" :value="occasion.value">{{ occasion.label }}</option></UiSelect></label>
      </template>
      <UiButton :icon="activeTab==='items' ? 'plus' : 'sparkles'" :disabled="activeTab==='looks' && items.length<2" @click="activeTab==='items' ? openItemCreate() : openLookCreate()">{{ activeTab==='items' ? 'Добавить' : 'Новый образ' }}</UiButton>
    </section>

    <nav v-if="activeTab==='items'" class="wardrobe-categories">
      <button v-for="category in categories" :key="category.value" type="button" :class="{active:categoryFilter===category.value}" @click="categoryFilter=categoryFilter===category.value?'all':category.value"><span><WardrobeGarmentIcon :category="category.value" /></span><b>{{ category.label }}</b><small>{{ countCategory(category.value) }}</small></button>
    </nav>

    <div v-if="activeTab==='items' && filteredItems.length" class="wardrobe-grid">
      <WardrobeItemCard v-for="item in filteredItems" :key="item.id" :item="item" :image-url="imageUrls[item.id]||''" :editable="isOwn(item)" :category-label="categoryMeta(item.category).label" @favorite="toggleItemFavorite(item)" @edit="openItemEdit(item)" @delete="openDelete('item',item)" />
    </div>
    <div v-else-if="activeTab==='looks' && filteredLooks.length" class="looks-grid">
      <WardrobeLookCard v-for="look in filteredLooks" :key="look.id" :look="look" :items="lookItems(look)" :image-urls="imageUrls" :editable="isOwn(look)" :occasion-label="occasionMeta(look.occasion).label" @edit="openLookEdit(look)" @delete="openDelete('look',look)" />
    </div>

    <section v-else class="wardrobe-empty panel">
      <span><UiIcon :name="activeTab==='items' ? 'hanger' : 'sparkles'" /></span>
      <strong>{{ emptyTitle }}</strong><p>{{ emptyDescription }}</p>
      <UiButton v-if="!search" :icon="activeTab==='items' ? 'plus' : 'sparkles'" :disabled="activeTab==='looks' && items.length<2" @click="activeTab==='items' ? openItemCreate() : openLookCreate()">{{ activeTab==='items' ? 'Добавить первую вещь' : 'Собрать первый образ' }}</UiButton>
    </section>

    <UiModal v-model="isItemModalOpen" :title="editingItem ? 'Изменить вещь' : 'Новая вещь'" eyebrow="Шкаф" width="760px" :close-on-overlay="!isSaving">
      <form class="wardrobe-editor" @submit.prevent="saveItem">
        <div class="wardrobe-photo" :style="{ '--item-color': itemForm.color }">
          <img v-if="photoPreview" :src="photoPreview" alt="Предпросмотр вещи">
          <WardrobeGarmentIcon v-else :category="itemForm.category" />
          <div v-if="isRemovingBackground" class="wardrobe-photo__processing"><UiIcon name="refresh"/><span>Убираем фон…</span></div>
          <label :class="{ disabled:isRemovingBackground }"><UiIcon name="camera"/><span>{{ photoPreview ? 'Заменить фото' : 'Добавить фото' }}</span><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="isRemovingBackground" @change="selectPhoto"></label>
        </div>
        <div class="wardrobe-editor__fields">
          <UiInput v-model="itemForm.name" label="Название" placeholder="Зелёная рубашка" required :error="itemErrors.name" />
          <label><span>Категория</span><UiSelect v-model="itemForm.category"><option v-for="category in categories" :key="category.value" :value="category.value">{{ category.label }}</option></UiSelect></label>
          <UiInput v-model="itemForm.brand" label="Бренд" placeholder="Необязательно" />
          <UiInput v-model="itemForm.size" label="Размер" placeholder="M, 43, one size…" />
          <label><span>Доступ</span><UiSelect v-model="itemForm.visibility"><option value="private">Только мне</option><option value="shared">Участникам пространства</option></UiSelect></label>
        </div>
        <section class="wardrobe-options"><div><span>Цвет</span><UiColorPicker v-model="itemForm.color" label="Цвет вещи" :colors="colors" /></div><div><span>Сезон</span><div class="season-pills"><button v-for="season in seasons" :key="season" type="button" :class="{active:itemForm.seasons.includes(season)}" @click="toggleSeason(season)">{{ season }}</button></div></div></section>
        <UiInput v-model="itemForm.note" type="textarea" label="Заметка" placeholder="С чем носить, особенности ухода или ссылка" />
        <label class="wardrobe-favorite"><button type="button" :class="{active:itemForm.favorite}" @click="itemForm.favorite=!itemForm.favorite"><UiIcon name="star"/></button><span><strong>Любимая вещь</strong><small>Будет отображаться первой.</small></span></label>
        <p v-if="itemErrors.save" class="wardrobe-error">{{ itemErrors.save }}</p>
        <footer><UiButton type="button" variant="secondary" :disabled="isSaving" @click="isItemModalOpen=false">Отмена</UiButton><UiButton type="submit" :loading="isSaving" :disabled="isRemovingBackground">Сохранить вещь</UiButton></footer>
      </form>
    </UiModal>

    <UiModal v-model="isLookModalOpen" :title="editingLook ? 'Изменить образ' : 'Новый образ'" eyebrow="Конструктор образов" fullscreen :close-on-overlay="!isSaving">
      <form class="look-editor look-editor--fullscreen" @submit.prevent="saveLook">
        <div class="look-editor__fields"><UiInput v-model="lookForm.title" label="Название образа" placeholder="На прогулку вечером" required :error="lookErrors.title"/><label><span>Ситуация</span><UiSelect v-model="lookForm.occasion"><option v-for="occasion in occasions" :key="occasion.value" :value="occasion.value">{{ occasion.label }}</option></UiSelect></label><label><span>Доступ</span><UiSelect v-model="lookForm.visibility"><option value="private">Только мне</option><option value="shared">Участникам пространства</option></UiSelect></label></div>
        <section class="look-picker"><header><div><strong>Выберите вещи</strong><small>{{ lookForm.itemIds.length }} выбрано</small></div><UiInput v-model="lookSearch" type="search" placeholder="Поиск по шкафу"/></header><div class="look-picker__grid"><button v-for="item in selectableItems" :key="item.id" type="button" :class="{active:lookForm.itemIds.includes(item.id)}" @click="toggleLookItem(item.id)"><span :style="{'--item-color':item.color}"><img v-if="imageUrls[item.id]" :src="imageUrls[item.id]" :alt="item.name"><WardrobeGarmentIcon v-else :category="item.category"/></span><b>{{ item.name }}</b><small>{{ categoryMeta(item.category).label }}</small><i><UiIcon name="check"/></i></button></div><p v-if="lookErrors.items" class="wardrobe-error">{{ lookErrors.items }}</p></section>
        <section class="look-composer"><header><div><strong>Расположите вещи</strong><small>Перетаскивайте и накладывайте фотографии друг на друга</small></div></header><WardrobeLookCanvas v-model="lookForm.layout" :items="selectedLookItems" :image-urls="imageUrls" editable @reset="resetLookLayout" /></section>
        <UiInput v-model="lookForm.note" type="textarea" label="Заметка" placeholder="Для какой погоды или случая подходит" />
        <label class="wardrobe-favorite"><button type="button" :class="{active:lookForm.favorite}" @click="lookForm.favorite=!lookForm.favorite"><UiIcon name="star"/></button><span><strong>Любимый образ</strong><small>Будет отображаться первым.</small></span></label>
        <p v-if="lookErrors.save" class="wardrobe-error">{{ lookErrors.save }}</p>
        <footer><UiButton type="button" variant="secondary" :disabled="isSaving" @click="isLookModalOpen=false">Отмена</UiButton><UiButton type="submit" :loading="isSaving">Сохранить образ</UiButton></footer>
      </form>
    </UiModal>

    <UiModal v-model="isDeleteOpen" :title="deleteKind==='item' ? 'Удалить вещь?' : 'Удалить образ?'" eyebrow="Шкаф" width="430px"><div class="wardrobe-delete"><span><UiIcon name="trash"/></span><strong>{{ deletingEntity?.name || deletingEntity?.title }}</strong><p>{{ deleteKind==='item' ? 'Вещь также исчезнет из ваших сохранённых образов.' : 'Состав образа будет удалён.' }}</p><footer><UiButton variant="secondary" @click="isDeleteOpen=false">Отмена</UiButton><UiButton variant="danger" :loading="isDeleting" @click="confirmDelete">Удалить</UiButton></footer></div></UiModal>
  </section>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import UiButton from '../../../components/ui/UiButton.vue'
import UiColorPicker from '../../../components/ui/UiColorPicker.vue'
import UiIcon from '../../../components/ui/UiIcon.vue'
import UiInput from '../../../components/ui/UiInput.vue'
import UiModal from '../../../components/ui/UiModal.vue'
import UiPageHeader from '../../../components/ui/UiPageHeader.vue'
import UiSelect from '../../../components/ui/UiSelect.vue'
import { useNotification } from '../../../composables/ui/useNotification.js'
import { authStore } from '../../../stores/auth.store.js'
import { wardrobeStore } from '../../../stores/wardrobe.store'
import { workspaceStore } from '../../../stores/workspace.store.js'
import type { WardrobeCategory, WardrobeItem, WardrobeLook, WardrobeLookPlacement, WardrobeOccasion, WardrobeVisibility } from '../../../types/wardrobe'
import { createWardrobeImageUrl, removeWardrobeImage, uploadWardrobeImage } from '../api/wardrobeImages.api'
import WardrobeGarmentIcon from '../components/WardrobeGarmentIcon.vue'
import WardrobeItemCard from '../components/WardrobeItemCard.vue'
import WardrobeLookCanvas from '../components/WardrobeLookCanvas.vue'
import WardrobeLookCard from '../components/WardrobeLookCard.vue'
import { createWardrobeCutoutUrl, removeWardrobeImageBackground } from '../services/wardrobeBackgroundRemoval.service'
import { reconcileLookLayout } from '../utils/wardrobeLookLayout'

type ItemForm={name:string;category:WardrobeCategory;color:string;seasons:string[];brand:string;size:string;note:string;visibility:WardrobeVisibility;favorite:boolean}
type LookForm={title:string;itemIds:string[];layout:WardrobeLookPlacement[];occasion:WardrobeOccasion;note:string;visibility:WardrobeVisibility;favorite:boolean}
const categories:Array<{value:WardrobeCategory;label:string}>=[{value:'top',label:'Верх'},{value:'bottom',label:'Низ'},{value:'outerwear',label:'Верхняя одежда'},{value:'shoes',label:'Обувь'},{value:'onepiece',label:'Платья и костюмы'},{value:'accessory',label:'Аксессуары'}]
const occasions:Array<{value:WardrobeOccasion;label:string}>=[{value:'everyday',label:'На каждый день'},{value:'work',label:'Работа'},{value:'outing',label:'Выход и встреча'},{value:'sport',label:'Спорт'},{value:'home',label:'Дом'},{value:'other',label:'Другое'}]
const seasons=['Весна','Лето','Осень','Зима']
const colors=['#111827','#475569','#e5e7eb','#f8fafc','#166534','#0f766e','#1d4ed8','#7c3aed','#be123c','#dc2626','#ea580c','#ca8a04','#92400e']
const {notify}=useNotification();const items=wardrobeStore.items;const looks=wardrobeStore.looks
const activeTab=ref<'items'|'looks'>('items'),search=ref(''),lookSearch=ref(''),categoryFilter=ref<'all'|WardrobeCategory>('all'),occasionFilter=ref<'all'|WardrobeOccasion>('all')
const isItemModalOpen=ref(false),isLookModalOpen=ref(false),isDeleteOpen=ref(false),isSaving=ref(false),isDeleting=ref(false),isRemovingBackground=ref(false),editingItem=ref<WardrobeItem|null>(null),editingLook=ref<WardrobeLook|null>(null),deletingEntity=ref<WardrobeItem|WardrobeLook|null>(null),deleteKind=ref<'item'|'look'>('item')
const itemForm=reactive<ItemForm>(emptyItem()),lookForm=reactive<LookForm>(emptyLook()),itemErrors=reactive({name:'',save:''}),lookErrors=reactive({title:'',items:'',save:''}),selectedPhoto=ref<File|null>(null),localPhotoUrl=ref(''),imageUrls=reactive<Record<string,string>>({})
const photoPreview=computed(()=>localPhotoUrl.value||(editingItem.value?imageUrls[editingItem.value.id]||'':''))
const filteredItems=computed(()=>items.value.filter(item=>{const q=norm(search.value);return(categoryFilter.value==='all'||item.category===categoryFilter.value)&&(!q||norm([item.name,item.brand,item.size,item.note].join(' ')).includes(q))}))
const filteredLooks=computed(()=>looks.value.filter(look=>(occasionFilter.value==='all'||look.occasion===occasionFilter.value)&&(!norm(search.value)||norm([look.title,look.note].join(' ')).includes(norm(search.value)))))
const selectableItems=computed(()=>items.value.filter(item=>!norm(lookSearch.value)||norm(item.name).includes(norm(lookSearch.value))))
const selectedLookItems=computed(()=>lookForm.itemIds.map(id=>items.value.find(item=>item.id===id)).filter((item):item is WardrobeItem=>Boolean(item)))
const activeItemsCount=computed(()=>items.value.length),favoriteCount=computed(()=>items.value.filter(i=>i.favorite).length+looks.value.filter(i=>i.favorite).length)
const emptyTitle=computed(()=>search.value?'Ничего не найдено':activeTab.value==='items'?'Шкаф пока пуст':'Образов пока нет'),emptyDescription=computed(()=>search.value?'Измените поиск или фильтры.':activeTab.value==='items'?'Добавьте вещи с фотографиями или используйте аккуратные иллюстрации.':'Выберите минимум две вещи и сохраните готовое сочетание.')
watch(items,async current=>{await Promise.all(current.map(loadItemImage))},{immediate:true,deep:true})
watch(isItemModalOpen,(isOpen)=>{if(!isOpen)resetPhoto()})
function emptyItem():ItemForm{return{name:'',category:'top',color:'#166534',seasons:[],brand:'',size:'',note:'',visibility:'private',favorite:false}}
function emptyLook():LookForm{return{title:'',itemIds:[],layout:[],occasion:'everyday',note:'',visibility:'private',favorite:false}}
function openItemCreate(){editingItem.value=null;Object.assign(itemForm,emptyItem());resetPhoto();itemErrors.name='';itemErrors.save='';isItemModalOpen.value=true}
function openItemEdit(item:WardrobeItem){editingItem.value=item;Object.assign(itemForm,{name:item.name,category:item.category,color:item.color,seasons:[...item.seasons],brand:item.brand,size:item.size,note:item.note,visibility:item.visibility,favorite:item.favorite});resetPhoto();itemErrors.name='';itemErrors.save='';isItemModalOpen.value=true}
function openLookCreate(){editingLook.value=null;Object.assign(lookForm,emptyLook());lookSearch.value='';lookErrors.title='';lookErrors.items='';lookErrors.save='';isLookModalOpen.value=true}
function openLookEdit(look:WardrobeLook){editingLook.value=look;Object.assign(lookForm,{title:look.title,itemIds:[...look.itemIds],layout:reconcileLookLayout(lookItems(look),look.layout),occasion:look.occasion,note:look.note,visibility:look.visibility,favorite:look.favorite});lookSearch.value='';isLookModalOpen.value=true}
async function selectPhoto(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;resetPhoto();isRemovingBackground.value=true;try{const cutout=await removeWardrobeImageBackground(file,file.name);selectedPhoto.value=cutout;localPhotoUrl.value=URL.createObjectURL(cutout)}catch{selectedPhoto.value=file;localPhotoUrl.value=URL.createObjectURL(file);notify('Не удалось убрать фон автоматически. Оригинал сохранён.','warning')}finally{isRemovingBackground.value=false;input.value=''}}
function resetPhoto(){if(localPhotoUrl.value)URL.revokeObjectURL(localPhotoUrl.value);localPhotoUrl.value='';selectedPhoto.value=null}
async function saveItem(){if(isRemovingBackground.value)return;itemErrors.name=itemForm.name.trim()?'':'Укажите название';if(itemErrors.name)return;isSaving.value=true;itemErrors.save='';let imagePath=editingItem.value?.imagePath||'';let uploaded='';if(selectedPhoto.value){const upload=await uploadWardrobeImage(selectedPhoto.value,workspaceStore.activeWorkspaceId.value);if(!upload.ok){itemErrors.save=upload.message;isSaving.value=false;return}imagePath=upload.path;uploaded=upload.path}const payload={...itemForm,status:'available' as const,name:itemForm.name.trim(),brand:itemForm.brand.trim(),size:itemForm.size.trim(),note:itemForm.note.trim(),seasons:[...itemForm.seasons],imagePath};const result=editingItem.value?await wardrobeStore.updateItem(editingItem.value.id,payload):await wardrobeStore.createItem(payload);if(!result.ok&&uploaded)await removeWardrobeImage(uploaded);if(result.ok&&editingItem.value?.imagePath&&uploaded)await removeWardrobeImage(editingItem.value.imagePath);isSaving.value=false;if(!result.ok){itemErrors.save=result.message||'Не удалось сохранить вещь';return}const savedId=editingItem.value?.id||result.item?.id;if(uploaded&&savedId){const signedUrl=await createWardrobeImageUrl(uploaded);imageUrls[savedId]=await createWardrobeCutoutUrl(signedUrl,uploaded)}isItemModalOpen.value=false;notify('Вещь сохранена','success')}
async function saveLook(){lookErrors.title=lookForm.title.trim()?'':'Укажите название';lookErrors.items=lookForm.itemIds.length>=2?'':'Выберите минимум две вещи';if(lookErrors.title||lookErrors.items)return;isSaving.value=true;const payload={...lookForm,title:lookForm.title.trim(),itemIds:[...lookForm.itemIds],note:lookForm.note.trim()};const result=editingLook.value?await wardrobeStore.updateLook(editingLook.value.id,payload):await wardrobeStore.createLook(payload);isSaving.value=false;if(!result.ok){lookErrors.save=result.message||'Не удалось сохранить образ';return}isLookModalOpen.value=false;notify('Образ сохранён','success')}
function openDelete(kind:'item'|'look',entity:WardrobeItem|WardrobeLook){deleteKind.value=kind;deletingEntity.value=entity;isDeleteOpen.value=true}
async function confirmDelete(){if(!deletingEntity.value)return;isDeleting.value=true;const entityId=deletingEntity.value.id;const imagePath=deleteKind.value==='item'?(deletingEntity.value as WardrobeItem).imagePath:'';const result=deleteKind.value==='item'?await wardrobeStore.removeItem(entityId):await wardrobeStore.removeLook(entityId);if(result.ok&&imagePath)await removeWardrobeImage(imagePath);if(result.ok&&deleteKind.value==='item')delete imageUrls[entityId];isDeleting.value=false;if(!result.ok)return notify(result.message||'Не удалось удалить','warning');isDeleteOpen.value=false;notify(deleteKind.value==='item'?'Вещь удалена':'Образ удалён','info')}
async function toggleItemFavorite(item:WardrobeItem){const result=await wardrobeStore.updateItem(item.id,{favorite:!item.favorite});if(!result.ok)notify(result.message,'warning')}
function toggleSeason(season:string){itemForm.seasons=itemForm.seasons.includes(season)?itemForm.seasons.filter(x=>x!==season):[...itemForm.seasons,season]}
function toggleLookItem(id:string){lookForm.itemIds=lookForm.itemIds.includes(id)?lookForm.itemIds.filter(x=>x!==id):[...lookForm.itemIds,id];lookForm.layout=reconcileLookLayout(selectedLookItems.value,lookForm.layout)}
function resetLookLayout(){lookForm.layout=reconcileLookLayout(selectedLookItems.value,[])}
function lookItems(look:WardrobeLook){return look.itemIds.map(id=>items.value.find(item=>item.id===id)).filter((item):item is WardrobeItem=>Boolean(item))}
function countCategory(category:WardrobeCategory){return items.value.filter(i=>i.category===category).length}
function categoryMeta(value:WardrobeCategory){return categories.find(x=>x.value===value)||categories[0]}
function occasionMeta(value:WardrobeOccasion){return occasions.find(x=>x.value===value)||occasions[0]}
function isOwn(entity:WardrobeItem|WardrobeLook){return entity.ownerId===authStore.currentUserId.value}
function norm(value:string){return value.toLocaleLowerCase('ru-RU').replace(/ё/g,'е').trim()}
async function loadItemImage(item:WardrobeItem){if(!item.imagePath||imageUrls[item.id])return;const signedUrl=await createWardrobeImageUrl(item.imagePath);imageUrls[item.id]=await createWardrobeCutoutUrl(signedUrl,item.imagePath)}
</script>

